// Simulates the Google Ads API: returns daily rows per campaign × ad group × device.
 // In production, replace this node with a real Google Ads API call.

 const data = $input.first().json.data ?? [];
 const dates = data.map(row => row.date).filter(Boolean);
 if (dates.length === 0) return [];   // nothing missing -> stop quietly

 // campaign_id: [type, daily budget, conversion rate]
 const campaigns = {
   101: ['Search', 150, 0.08],   102: ['Search', 400, 0.03],  103: ['Search', 250, 0.015],
   104: ['Search', 350, 0.03],   105: ['PMax', 600, 0.025],   106: ['PMax', 450, 0.025],
   107: ['Display', 200, 0.006], 108: ['Display', 300, 0.003],
   109: ['YouTube', 350, 0.0008], 110: ['Search', 180, 0.03],
 };
 const ctrByType = { Search: 0.065, PMax: 0.022, Display: 0.006, YouTube: 0.004 };
 const cpcByType = { Search: 1.9, PMax: 1.4, Display: 0.35, YouTube: 0.12 };
 const devices = { Mobile: 0.62, Desktop: 0.31, Tablet: 0.07 };
 const adGroups = ['Core', 'Offers', 'Long-tail'];
 const rand = (min, max) => min + Math.random() * (max - min);

 const rows = [];
 for (const date of dates) {
   const dow = new Date(date + 'T00:00:00Z').getUTCDay();   // 5 = Fri, 6 = Sat
   const season = (dow === 5 || dow === 6) ? 0.85 : 1.0;

   for (const [id, [type, budget, cvr]] of Object.entries(campaigns)) {
     for (const adGroup of adGroups) {
       for (const [device, share] of Object.entries(devices)) {
         const ctr = ctrByType[type], cpc = cpcByType[type];
         const impressions = Math.round(budget / cpc / ctr / 3 * share * season * rand(0.8, 1.2));
         const clicks = Math.round(impressions * ctr * (device === 'Desktop' ? 1.15 : 1) * rand(0.85, 1.15));
         const cost = +(clicks * cpc * rand(0.85, 1.15)).toFixed(2);
         const conversions = +(clicks * cvr * (device === 'Mobile' ? 0.8 : 1.15) * rand(0.7, 1.3)).toFixed(2);
         const value = Number(id) === 110 ? 0 : +(conversions * 300 * rand(0.8, 1.2)).toFixed(2);

         rows.push({ date, campaign_id: Number(id), ad_group: adGroup, device,
                     impressions, clicks, cost, conversions, conversion_value: value });
       }
     }
   }
 }

 // ClickHouse JSONEachRow format = one JSON object per line
 return [{ json: {
   dates,
   row_count: rows.length,
   body: rows.map(r => JSON.stringify(r)).join('\n'),
 }}];
